def get_unpacked_marks(
    obj: Union[object, type],
    *,
    consider_mro: bool = True,
) -> List[Mark]:
    """Obtain the unpacked marks that are stored on an object.

    If obj is a class and consider_mro is true, return marks for every class
    in the MRO.
    """
    if isinstance(obj, type) and consider_mro:
        mark_lists = [
            getattr(x, "pytestmark", [])
            for x in obj.__mro__
            if "pytestmark" in x.__dict__
        ]
    else:
        mark_lists = [getattr(obj, "pytestmark", [])]
    mark_list: List[Mark] = []
    for marks in mark_lists:
        if not isinstance(marks, list):
            marks = [marks]
        mark_list.extend(normalize_mark_list(marks))
    return mark_list

